"""Shared dark operations-console styling."""
import streamlit as st

def apply_theme():
 st.markdown("""<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
:root{--bg:#0B0D10;--surface:#11151A;--surface2:#161B22;--border:#222A33;--text:#F4F6F8;--muted:#8E99A8;--blue:#4C8DFF;--green:#34C98F;--yellow:#F3B44B;--red:#F05D68}html,body,[data-testid="stAppViewContainer"]{background:var(--bg);color:var(--text);font-family:Inter,Arial,sans-serif}[data-testid="stHeader"],footer{display:none}[data-testid="stSidebar"]{background:#101318;border-right:1px solid var(--border)}[data-testid="stSidebar"] *{color:var(--text)}.block-container{padding:1.5rem 2rem 2rem;max-width:1500px}.eyebrow{font-size:12px;letter-spacing:.09em;color:var(--muted);font-weight:700}.page-title{font-size:32px;font-weight:700;margin:2px 0}.subtle{color:var(--muted);font-size:14px}.card{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:16px;margin-bottom:12px}.metric-label{font-size:12px;color:var(--muted);font-weight:600;letter-spacing:.05em}.metric-value{font-size:31px;font-weight:700;line-height:1.2;margin:5px 0}.metric-detail{font-size:13px;color:var(--muted)}.status{font-size:12px;font-weight:700;letter-spacing:.07em}.status.normal{color:var(--green)}.status.warning{color:var(--yellow)}.status.critical{color:var(--red)}button[kind="secondary"]{border-color:var(--border)!important;background:var(--surface2)!important}div[data-baseweb="select"]>div{background:var(--surface2)!important;border-color:var(--border)!important} </style>""",unsafe_allow_html=True)
